SELECT [StockItemID],[StockItemName],[SupplierID],[ColorID],[UnitPackageID],[OuterPackageID],[Brand],[Size],[LeadTimeDays],[QuantityPerOuter],[IsChillerStock],[Barcode],[TaxRate],[UnitPrice],[RecommendedRetailPrice],[TypicalWeightPerUnit],[MarketingComments],[InternalComments],[CustomFields],[Tags],[SearchDetails],[LastEditedBy],CONVERT(nvarchar(33),[ValidFrom],126) AS [ValidFrom],CONVERT(nvarchar(33),[ValidTo],126) AS [ValidTo] FROM [Warehouse].[StockItems] ORDER BY [StockItemID]